_flavorDataProvider: {
  QueryInterface: ChromeUtils.generateQI(["nsIFlavorDataProvider"]),

  getFlavorData(transferable, flavor) {
    if (flavor !== "application/x-moz-file-promise") {
      return;
    }

    const fileName = {};
    transferable.getTransferData(
      "application/x-moz-file-promise-dest-filename",
      fileName
    );
    fileName.value.QueryInterface(Ci.nsISupportsString);

    const destDir = {};
    transferable.getTransferData(
      "application/x-moz-file-promise-dir",
      destDir
    );
    destDir.value.QueryInterface(Ci.nsIFile);

    const messageURI = {};
    transferable.getTransferData("text/plain", messageURI);
    messageURI.value.QueryInterface(Ci.nsISupportsString);

    // Don't overwrite an existing file, use a numbered file name instead.
    IOUtils.createUniqueFile(destDir.value.path, fileName.value.data)
      .then(path => MessageSaver.saveToFile(messageURI.value.data, path))
      .catch(console.error);
  },
},

_jsTree: {
  QueryInterface: ChromeUtils.generateQI(["nsIMsgJSTree"]),
  _inBatch: 0,
  beginUpdateBatch() {
    this._inBatch++;
  },
  endUpdateBatch() {
    this._inBatch--;
    if (this._inBatch < 0) {
      this._inBatch = 0;
      console.warn("Mismatch in batch processing detected.");
    }
